WITH filtered AS (SELECT *, CONCAT_WS('-', page, event_type) AS page_event_type_key, COALESCE(page, 'N/A') AS page_clean FROM web_events WHERE event_time > DATE '2023-08-29' AND page IS NOT NULL) SELECT id, page, event_time, duration_sec, page_event_type_key, page_clean, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_2_prior, LAG(duration_sec, 2) OVER w_running AS prev_duration_sec, AVG(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_6_prior, AVG(duration_sec) OVER (PARTITION BY YEAR(event_time), page) AS event_time_year_avg_duration_sec, FIRST_VALUE(duration_sec) IGNORE NULLS OVER w_recent AS first_known_duration_sec FROM filtered WHERE duration_sec <= 344 WINDOW w_running AS (PARTITION BY session_id ORDER BY duration_sec, id), w_recent AS (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
